23	{{- if and .Values.apiServer.enabled (semverCompare ">=3.0.0" .Values.airflowVersion) (or .Values.ingress.apiServer.enabled .Values.ingress.enabled) }}
24	{{- $fullname := include "airflow.fullname" . }}
25	apiVersion: networking.k8s.io/v1
26	kind: Ingress
27	metadata:
28	  name: {{ $fullname }}-ingress
29	  labels:
30	    tier: airflow
31	    component: airflow-ingress
32	    release: {{ .Release.Name }}
33	    chart: "{{ .Chart.Name }}-{{ .Chart.Version }}"
34	    heritage: {{ .Release.Service }}
